import sys

def subsets_brute(nums):
    n = len(nums)
    res = []
    for mask in range(1, 1 << n):
        cur = [nums[i] for i in range(n) if mask & (1 << i)]
        res.append(cur)
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for sub in subsets_brute(nums):
        print(' '.join(map(str, sub)))

import sys

def subsets_best(nums):
    res = [[]]
    for x in nums:
        res.extend([cur + [x] for cur in res])
    # 过滤空集并按字典序
    return sorted(cur for cur in res if cur)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for sub in subsets_best(nums):
        print(' '.join(map(str, sub)))
